/*
 * A263716  Irregular triangle read by rows: numbers in the Collatz conjecture
 *          in the order of their first appearance.
 * https://oeis.org/A263716
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf, easy, nice
 * Formula:   a(n) is generated by sequentially processing the Collatz *
 *            trajectories of successive starting numbers, emitting each
 *            number only * when it first appears in any row
 * Range:     u8 n <= 56, u16 n <= 1529, u32 n <= 19999, u64 n <= 19999,
 *            u128 n <= 19999, big any n
 * Validated: standard, pass, 80 terms through n = 9935 (2026-11-03)
 * Helpers:   mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <stddef.h>
#include "../utils/mem.h"

#if defined(__SIZEOF_INT128__)
#include <stdint.h>

/* Simple multiplicative hash for 0…UINT64_MAX */
static inline size_t seq_hash(seq_t x)
{
    uint64_t h = (uint64_t)x;
    /* Knuth multiplicative method */
    h *= 11400714785074694791ULL;
    return (size_t)h;
}
#define HAVE_INT128 1
#else
#define HAVE_INT128 0
#endif

/* Hash table for seen numbers */
static seq_t *hash_tab   = NULL;
static size_t  hash_cap  = 0;   /* must be a power of two */
static size_t  hash_used = 0;

/* Sequence storage */
static seq_t *seq      = NULL;
static size_t seq_cap  = 0;
static size_t seq_len  = 0;

/* Next starting value to test */
static idx_t next_start = 1;

/* Ensure the hash table has space for another element */
static void hash_expand(void)
{
    size_t new_cap = hash_cap * 2;
    seq_t *new_tab = mem_new(seq_t, new_cap);
    if (!new_tab) exit(1);
    mem_set(new_tab, 0, new_cap * sizeof(seq_t));

    for (size_t i = 0; i < hash_cap; ++i) {
        seq_t val = hash_tab[i];
        if (!val) continue;
        size_t h = seq_hash(val);
        size_t idx = h & (new_cap - 1);
        while (new_tab[idx]) idx = (idx + 1) & (new_cap - 1);
        new_tab[idx] = val;
    }
    mem_free(hash_tab);
    hash_tab = new_tab;
    hash_cap = new_cap;
}

/* Check whether x is already seen */
static bool hash_contains(seq_t x)
{
    if (!hash_cap) return false;
    size_t h   = seq_hash(x);
    size_t idx = h & (hash_cap - 1);
    while (hash_tab[idx]) {
        if (hash_tab[idx] == x) return true;
        idx = (idx + 1) & (hash_cap - 1);
    }
    return false;
}

/* Insert a new seen number */
static void hash_insert(seq_t x)
{
    if (!hash_cap) {
        hash_cap = 8;
        hash_tab = mem_new(seq_t, hash_cap);
        if (!hash_tab) exit(1);
        mem_set(hash_tab, 0, hash_cap * sizeof(seq_t));
    }
    if (hash_used * 2 >= hash_cap) hash_expand();

    size_t h   = seq_hash(x);
    size_t idx = h & (hash_cap - 1);
    while (hash_tab[idx]) idx = (idx + 1) & (hash_cap - 1);
    hash_tab[idx] = x;
    ++hash_used;
}

/* Grow the sequence array if necessary */
static void seq_grow(void)
{
    if (seq_len < seq_cap) return;
    size_t new_cap = seq_cap ? seq_cap * 2 : 4;
    seq_t *new_se;
    if (!seq) new_se = mem_new(seq_t, new_cap);
    else     new_se = mem_resize(seq_t, seq, new_cap);
    if (!new_se) exit(1);
    if (!seq) mem_set(new_se, 0, new_cap * sizeof(seq_t));
    seq     = new_se;
    seq_cap = new_cap;
}

seq_t a(idx_t n)
{
    /* Ensure we have at least n+1 terms */
    while (seq_len <= (size_t)n) {
        /* Find the next unseen starting number */
        while (hash_contains(next_start)) ++next_start;
        seq_t current = next_start;

        /* Emit the trajectory of current until a seen number appears */
        while (1) {
            seq_grow();
            seq[seq_len++] = current;
            hash_insert(current);

            if (current == 1) break;
            seq_t next;
            if (current & 1) {
#if HAVE_INT128
                __uint128_t tmp = (__uint128_t)current * 3 + 1;
                next = (seq_t)tmp;
#else
                /* Fall back; may overflow if very large */
                next = current * 3 + 1;
#endif
            } else {
                next = current >> 1;
            }
            if (hash_contains(next)) break;
            current = next;
        }
        ++next_start;   /* advance to the next potential start */
    }
    return seq[(size_t)n];
}
